// New 1-2 star reviews that mention a problem, grouped by app, as one Slack message.
const items = $input.all().map(i => i.json);
const alerts = items.filter(r => r.type === 'review' && r.status === 'new' && r.isAlert);
const summaries = items.filter(r => r.type === 'app_summary');
const lines = alerts.slice(0, 20).map(r => `• *${r.appName}* ${'★'.repeat(r.rating)} v${r.version ?? '?'} — ${String(r.text).slice(0, 180)} _(${(r.alertTerms || []).join(', ')})_`);
const signed = v => (v === undefined || v === null) ? 'n/a' : (v > 0 ? '+' : '') + v;
const trend = summaries
  .filter(s => s.ratingTrend === 'declining' || (s.latestVersionVsPreviousRating ?? 0) <= -0.5)
  .map(s => `:warning: *${s.appName}*: 7-day rating ${s.last7DaysAvgRating} vs ${s.previous7DaysAvgRating}; latest version ${s.latestVersion}: ${signed(s.latestVersionVsPreviousRating)} stars vs previous version`);
const text = (lines.length || trend.length)
  ? [':rotating_light: Google Play review alerts', ...trend, ...lines].join('\n')
  : `No new problem reviews today (${summaries.length} apps checked).`;
return [{ json: { text } }];
